contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: call forward with callee and data that triggers a failing external call.
    // The rule: the forward call must revert when the low-level call returns false.
    function check(address callee, bytes memory data) public {
        // We do not know callee's implementation here; require that calling it via a low-level call
        // returns false when invoked from this contract to ensure the mutant changes behavior.
        (bool ok,) = callee.call(data);
        // If the direct low-level call from the test already succeeds, this setup is not useful.
        require(!ok);

        // Now invoke c.forward which in the original contract will propagate the failure (revert).
        // In the mutant it will swallow the failure and return normally. We assert that c.forward reverted.
        bool reverted = false;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Property: c.forward must revert when the underlying low-level call fails.
        assert(reverted == true);
    }

    // Allow receiving ETH if callee needs it
    receive() external payable {}
    fallback() external payable {}
}

