pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: arbitrary bytes to forward; the adversarial callee will revert regardless of the data
    function testFuzz_property(bytes memory data) public {
        // deploy a callee that always reverts on fallback/call
        Reverter reverter = new Reverter();

        // try calling c.forward to the reverter; reference should revert for all inputs
        bool ok;
        try c.forward(address(reverter), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: for any callee that reverts, C.forward should revert (i.e., ok == false).
        // The mutant that removed the require would make ok == true for some inputs (indeed for all inputs here),
        // so this single assertion passes on the reference for all fuzz inputs and fails on the mutant.
        assertTrue(ok == false);
    }
}

// adversarial helper: always revert on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive performs a single call to c.forward and asserts that when the external
    // callee would succeed, c.forward does not revert. We observe success of the
    // external call by invoking the callee directly here before forwarding.
    // Parameters:
    // - callee: address of a contract with an externally callable function encoded in data
    // - data: calldata to send both directly and via c.forward
    function drive(address callee, bytes calldata data) public {
        // Precondition: the direct call must succeed (we require the callee's call with the same data returns true)
        (bool okDirect, ) = callee.call(data);
        require(okDirect, "precondition: callee must succeed when called directly");

        // Now call through c.forward. This is the state-changing call under test.
        c.forward(callee, data);

        // The distinguishing rule: since the direct call succeeded, forwarding must not revert.
        // If the mutant inverted the require, the forward would have reverted here and this assert would never be reached.
        assert(true);
    }

    // Provide a payable fallback so this test contract can hold/send ether if needed by callee.
    receive() external payable {}
}

